package com.bank.orgchart.service;

import com.bank.orgchart.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class OrgChartService {
    private static final Logger log = Logger.getLogger(OrgChartService.class.getName());

    public List<String> uniqueDepartments(List<Employee> employees) {
        log.info(() -> "Deriving unique departments from " + employees.size() + " employees");
        return employees.stream()
                .map(Employee::getDepartment)  // project to department
                .distinct()                    // drop repeats (String equals/hashCode)
                .collect(Collectors.toList());
    }
}
