package com.bank.orgchart;

import com.bank.orgchart.model.Employee;
import com.bank.orgchart.service.OrgChartService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT"),
            new Employee("Priya",  "Sales"),
            new Employee("Amit",   "IT"),     // repeat IT
            new Employee("Neha",   "HR"),
            new Employee("Karan",  "Sales")   // repeat Sales
        );

        List<String> depts = new OrgChartService().uniqueDepartments(staff);
        log.info(() -> "Unique departments: " + depts);
    }
}
